import Foundation

/// Looks up a UI string by its English text. Keys live in
/// Resources/<lang>.lproj/Localizable.strings (generated by Scripts/l10n.py).
/// Unknown keys fall back to the English text, so nothing ever shows a key.
func L(_ key: String) -> String {
    NSLocalizedString(key, tableName: nil, bundle: .main, value: key, comment: "")
}

/// Formatted lookup: the key holds `%@` / `%d` placeholders.
func L(_ key: String, _ arguments: CVarArg...) -> String {
    String(format: L(key), locale: Locale.current, arguments: arguments)
}
